(function (root) {
  var START = 10000;
  var FEE = 0.0005;

  function num(v, d) {
    var n = Number(v);
    return isFinite(n) ? n : d || 0;
  }

  function computeEquityCurve(trades, bars, startingCapital) {
    var cap = num(startingCapital, START);
    if (!bars || !bars.length) return [];
    var eq = new Array(bars.length);
    var cash = cap;
    var units = 0;
    var side = 0;
    var entry = 0;
    var inn = {};
    var out = {};
    (trades || []).forEach(function (tr) {
      inn[tr.i0] = tr;
      out[tr.i1] = tr;
    });
    for (var i = 0; i < bars.length; i++) {
      var open = inn[i];
      if (open && !side) {
        units = cash / bars[i].close;
        entry = bars[i].close;
        side = open.side === "SHORT" ? -1 : 1;
        cash = 0;
      }
      if (side === 1) eq[i] = units * bars[i].close;
      else if (side === -1) eq[i] = units * (2 * entry - bars[i].close);
      else eq[i] = cash;
      if (out[i] && side) {
        cash = eq[i] * (1 - FEE);
        units = 0;
        side = 0;
        eq[i] = cash;
      }
    }
    return eq;
  }

  function computeDrawdown(equity) {
    var peak = (equity && equity[0]) || 0;
    return (equity || []).map(function (v) {
      var x = num(v, 0);
      if (x > peak) peak = x;
      return peak ? (x - peak) / peak : 0;
    });
  }

  function analyze(trades) {
    var closed = (trades || []).filter(function (t) {
      return t && t.exit != null && t.i1 != null;
    });
    var wins = closed.filter(function (t) {
      return num(t.pnlAbs) > 0;
    });
    var losses = closed.filter(function (t) {
      return num(t.pnlAbs) < 0;
    });
    var gp = wins.reduce(function (s, t) {
      return s + num(t.pnlAbs);
    }, 0);
    var gl = Math.abs(
      losses.reduce(function (s, t) {
        return s + num(t.pnlAbs);
      }, 0),
    );
    return {
      tradeCount: closed.length,
      winRate: closed.length ? wins.length / closed.length : 0,
      profitFactor: gl === 0 ? (gp > 0 ? Infinity : 0) : gp / gl,
      avgProfit: closed.length
        ? closed.reduce(function (s, t) {
            return s + num(t.pnlPct);
          }, 0) / closed.length
        : 0,
      avgWin: wins.length
        ? wins.reduce(function (s, t) {
            return s + num(t.pnlAbs);
          }, 0) / wins.length
        : 0,
      avgLoss: losses.length
        ? losses.reduce(function (s, t) {
            return s + num(t.pnlAbs);
          }, 0) / losses.length
        : 0,
    };
  }

  function pushTrade(trades, bars, side, entry, entryI, i) {
    var px = num(bars[i] && bars[i].close);
    var raw = side === "SHORT" ? entry - px : px - entry;
    var feeAbs = FEE * (entry + px);
    trades.push({
      side: side,
      entry: entry,
      exit: px,
      pnlPct: (raw / entry) * 100 - FEE * 200,
      pnlAbs: raw - feeAbs,
      open: false,
      i0: entryI,
      i1: i,
      t0: bars[entryI].time,
      t1: bars[i].time,
    });
  }

  function backtest(opts) {
    opts = opts || {};
    var bars = opts.bars || opts.inputSeries || [];
    var trades = [];
    var pos = 0;
    var entry = 0;
    var entryI = 0;
    var hold = num(opts.holdingDays, 0);
    var pred = opts.predicate || opts.enterLong;
    var exitFn = opts.exitLong;
    var i;
    for (i = 1; i < bars.length; i++) {
      var wantIn = false;
      var wantOut = false;
      if (typeof pred === "function") {
        try {
          wantIn = Boolean(pred(bars, i));
        } catch (e) {
          wantIn = false;
        }
      }
      if (typeof opts.entryRule === "function") {
        try {
          wantIn = wantIn || Boolean(opts.entryRule(bars[i], i, bars));
        } catch (e2) {
          /* ignore */
        }
      }
      if (typeof exitFn === "function") {
        try {
          wantOut = Boolean(exitFn(bars, i));
        } catch (e3) {
          wantOut = false;
        }
      }
      if (pos === 1) {
        var timed = hold > 0 && i - entryI >= hold;
        if (wantOut || timed || i === bars.length - 1) {
          pushTrade(trades, bars, "LONG", entry, entryI, i);
          pos = 0;
        }
      }
      if (pos === 0 && wantIn && i < bars.length - 1) {
        pos = 1;
        entry = num(bars[i].close);
        entryI = i;
      }
    }
    if (pos === 1 && bars.length) pushTrade(trades, bars, "LONG", entry, entryI, bars.length - 1);
    var equity = computeEquityCurve(trades, bars, opts.startingCapital);
    var drawdown = computeDrawdown(equity);
    return {
      trades: trades,
      equity: equity,
      drawdown: drawdown,
      analysis: analyze(trades),
    };
  }

  function signalBars(bars, pred) {
    var idx = [];
    for (var i = 1; i < bars.length; i++) {
      var hit = false;
      try {
        hit = Boolean(pred(bars, i));
      } catch (e) {
        hit = false;
      }
      if (hit) idx.push(i);
    }
    return idx;
  }

  function entriesFromPredicate(bars, pred) {
    var idx = [];
    var prev = false;
    for (var i = 1; i < bars.length; i++) {
      var hit = false;
      try {
        hit = Boolean(pred(bars, i));
      } catch (e) {
        hit = false;
      }
      if (hit && !prev) idx.push(i);
      prev = hit;
    }
    return idx;
  }

  function holdingMatrix(bars, entryIdx, maxDays) {
    var days = maxDays || 10;
    var rows = [];
    var d;
    for (d = 1; d <= days; d++) {
      var rets = [];
      for (var k = 0; k < entryIdx.length; k++) {
        var i0 = entryIdx[k];
        var i1 = i0 + d;
        if (i1 >= bars.length) continue;
        var a = num(bars[i0].close);
        var b = num(bars[i1].close);
        if (a > 0) rets.push(b / a - 1);
      }
      var n = rets.length;
      var avg = n
        ? rets.reduce(function (s, x) {
            return s + x;
          }, 0) / n
        : 0;
      var mx = n ? Math.max.apply(null, rets) : 0;
      var mn = n ? Math.min.apply(null, rets) : 0;
      var ups = rets.filter(function (x) {
        return x > 0;
      });
      var dns = rets.filter(function (x) {
        return x < 0;
      });
      var avgWin = ups.length
        ? ups.reduce(function (s, x) {
            return s + x;
          }, 0) / ups.length
        : 0;
      var avgLoss = dns.length
        ? Math.abs(
            dns.reduce(function (s, x) {
              return s + x;
            }, 0) / dns.length,
          )
        : 0;
      rows.push({
        days: d,
        n: n,
        avg: avg,
        max: mx,
        min: mn,
        pl: avgLoss === 0 ? (avgWin > 0 ? Infinity : 0) : avgWin / avgLoss,
        up: n ? ups.length / n : 0,
        down: n ? dns.length / n : 0,
      });
    }
    return rows;
  }

  root.Grademark = {
    backtest: backtest,
    analyze: analyze,
    computeEquityCurve: computeEquityCurve,
    computeDrawdown: computeDrawdown,
    holdingMatrix: holdingMatrix,
    entriesFromPredicate: entriesFromPredicate,
    signalBars: signalBars,
  };
  root.grademark = root.Grademark;
})(typeof window !== "undefined" ? window : globalThis);
